fn resolve_line_height_length(context: &Context, length: NoCalcLength) -> CSSPixelLength {
    let result = length.to_computed_value_with_base_size(
        context,
        FontBaseSize::CurrentStyle,
        LineHeightBase::InheritedStyle,
    );
    if length.should_zoom_text() {
        context.maybe_zoom_text(result)
    } else {
        result
    }
}

fn map_line_height_leaf(context: &Context, leaf: &Leaf) -> Result<Leaf, ()> {
    let length = match leaf {
        Leaf::Percentage(p) => NoCalcLength::from_em(p.get()),
        Leaf::Length(l) => *l,
        _ => return leaf.to_computed_value(Some(context), None),
    };
    Ok(Leaf::Length(NoCalcLength::from_px(
        resolve_line_height_length(context, length).px(),
    )))
}

impl ToComputedValue for LineHeight {
    type ComputedValue = computed::LineHeight;

    #[inline]
    fn to_computed_value(&self, context: &Context) -> Self::ComputedValue {
        match self {
            GenericLineHeight::Normal => GenericLineHeight::Normal,
            GenericLineHeight::Number(number) => {
                let value = match number.as_calc() {
                    None => number.to_computed_value(context).0,
                    Some(calc) => {
                        let resolved = calc
                            .node
                            .resolve_map(|leaf| map_line_height_leaf(context, leaf));
                        let value = match resolved {
                            Ok(Leaf::Number(n)) => n.get(),
                            _ => {
                                debug_assert!(
                                    false,
                                    "Unexpected LineHeight number calc without resolved number"
                                );
                                f32::NAN
                            },
                        };
                        // The `NonNegative` clamping mode ensures that -infinity isn't produced
                        calc.clamping_mode
                            .clamp(crate::values::normalize(value).min(f32::MAX))
                    },
                };
                GenericLineHeight::Number(NonNegative(value))
            },
            GenericLineHeight::Length(non_negative_lp) => {
                let result = match non_negative_lp.0 {
                    LengthPercentage::Length(ref length) => {
                        resolve_line_height_length(context, *length)
                    },
                    LengthPercentage::Percentage(ref p) => {
                        resolve_line_height_length(context, NoCalcLength::from_em(p.get()))
                    },
                    LengthPercentage::Calc(ref calc) => calc
                        .to_computed_value_zoomed(
                            context,
                            FontBaseSize::CurrentStyle,
                            LineHeightBase::InheritedStyle,
                        )
                        .resolve(FontBaseSize::CurrentStyle.resolve(context).computed_size()),
                };
                GenericLineHeight::Length(result.into())
            },
        }
    }

    #[inline]
    fn from_computed_value(computed: &Self::ComputedValue) -> Self {
        match *computed {
            GenericLineHeight::Normal => GenericLineHeight::Normal,
            GenericLineHeight::Number(ref number) => {
                GenericLineHeight::Number(NonNegativeNumber::from_computed_value(number))
            },
            GenericLineHeight::Length(ref length) => {
                GenericLineHeight::Length(NoCalcLength::from_computed_value(&length.0).into())
            },
        }
    }
}

fn reference_font_size_and_length(
        &self,
        context: &Context,
        base_size: FontBaseSize,
        line_height_base: LineHeightBase,
    ) -> (computed::Length, CSSFloat) {
        fn query_font_metrics(
            context: &Context,
            base_size: FontBaseSize,
            orientation: FontMetricsOrientation,
            flags: QueryFontMetricsFlags,
        ) -> FontMetrics {
            context.query_font_metrics(base_size, orientation, flags)
        }

        fn ex_size(
            context: &Context,
            base_size: FontBaseSize,
            reference_font_size: &FontSize,
        ) -> computed::Length {
            let metrics = query_font_metrics(
                context,
                base_size,
                FontMetricsOrientation::Horizontal,
                QueryFontMetricsFlags::empty(),
            );
            metrics.x_height_or_default(reference_font_size.used_size())
        }

        fn ch_size(
            context: &Context,
            base_size: FontBaseSize,
            reference_font_size: &FontSize,
        ) -> computed::Length {
            let metrics = query_font_metrics(
                context,
                base_size,
                FontMetricsOrientation::MatchContextPreferHorizontal,
                QueryFontMetricsFlags::NEEDS_CH,
            );
            metrics.zero_advance_measure_or_default(
                reference_font_size.used_size(),
                context.style().writing_mode.is_upright(),
            )
        }

        fn cap_size(context: &Context, base_size: FontBaseSize) -> computed::Length {
            let metrics = query_font_metrics(
                context,
                base_size,
                FontMetricsOrientation::Horizontal,
                QueryFontMetricsFlags::empty(),
            );
            metrics.cap_height_or_default()
        }

        fn ic_size(
            context: &Context,
            base_size: FontBaseSize,
            reference_font_size: &FontSize,
        ) -> computed::Length {
            let metrics = query_font_metrics(
                context,
                base_size,
                FontMetricsOrientation::MatchContextPreferVertical,
                QueryFontMetricsFlags::NEEDS_IC,
            );
            metrics.ic_width_or_default(reference_font_size.used_size())
        }

        context
            .builder
            .add_flags(ComputedValueFlags::USES_FONT_OR_WM_RELATIVE_UNITS);

        let reference_font_size = base_size.resolve(context);
        let length = self.value;
        match self.unit {
            LengthUnit::Em => {
                if context.for_non_inherited_property && base_size == FontBaseSize::CurrentStyle {
                    context
                        .rule_cache_conditions
                        .borrow_mut()
                        .set_font_size_dependency(reference_font_size.computed_size);
                }

                (reference_font_size.computed_size(), length)
            },
            LengthUnit::Lh => {
                let reference_size = if context.in_media_query {
                    context
                        .device()
                        .calc_line_height(
                            context.default_style().get_font(),
                            context.style().writing_mode,
                            None,
                        )
                        .0
                } else {
                    let line_height = context.builder.calc_line_height(
                        context.device(),
                        line_height_base,
                        context.style().writing_mode,
                    );
                    if context.for_non_inherited_property
                        && line_height_base == LineHeightBase::CurrentStyle
                    {
                        context
                            .rule_cache_conditions
                            .borrow_mut()
                            .set_line_height_dependency(line_height)
                    }
                    line_height.0
                };
                (reference_size, length)
            },
            LengthUnit::Ex => (ex_size(context, base_size, &reference_font_size), length),
            LengthUnit::Ch => (ch_size(context, base_size, &reference_font_size), length),
            LengthUnit::Cap => (cap_size(context, base_size), length),
            LengthUnit::Ic => (ic_size(context, base_size, &reference_font_size), length),
            LengthUnit::Rex => {
                let reference_size = if context.builder.is_root_element || context.in_media_query {
                    ex_size(context, base_size, &reference_font_size)
                } else {
                    context
                        .device()
                        .root_font_metrics_ex()
                        .zoom(context.builder.effective_zoom)
                };
                (reference_size, length)
            },
            LengthUnit::Rch => {
                let reference_size = if context.builder.is_root_element || context.in_media_query {
                    ch_size(context, base_size, &reference_font_size)
                } else {
                    context
                        .device()
                        .root_font_metrics_ch()
                        .zoom(context.builder.effective_zoom)
                };
                (reference_size, length)
            },
            LengthUnit::Rcap => {
                let reference_size = if context.builder.is_root_element || context.in_media_query {
                    cap_size(context, base_size)
                } else {
                    context
                        .device()
                        .root_font_metrics_cap()
                        .zoom(context.builder.effective_zoom)
                };
                (reference_size, length)
            },
            LengthUnit::Ric => {
                let reference_size = if context.builder.is_root_element || context.in_media_query {
                    ic_size(context, base_size, &reference_font_size)
                } else {
                    context
                        .device()
                        .root_font_metrics_ic()
                        .zoom(context.builder.effective_zoom)
                };
                (reference_size, length)
            },
            LengthUnit::Rem => {
                let reference_size = if context.builder.is_root_element || context.in_media_query {
                    reference_font_size.computed_size()
                } else {
                    context
                        .device()
                        .root_font_size()
                        .zoom(context.builder.effective_zoom)
                };
                (reference_size, length)
            },
            LengthUnit::Rlh => {
                let reference_size = if context.builder.is_root_element {
                    context
                        .builder
                        .calc_line_height(
                            context.device(),
                            line_height_base,
                            context.style().writing_mode,
                        )
                        .0
                } else if context.in_media_query {
                    context
                        .device()
                        .calc_line_height(
                            context.default_style().get_font(),
                            context.style().writing_mode,
                            None,
                        )
                        .0
                } else {
                    context.device().root_line_height()
                };
                let reference_size = if context.builder.is_root_element {
                    reference_size
                } else {
                    reference_size.zoom(context.builder.effective_zoom)
                };
                (reference_size, length)
            },
            _ => unreachable!("reference_font_size_and_length: not a font-relative unit"),
        }
    }

pub fn to_computed_value_with_base_size(
        &self,
        context: &Context,
        base_size: FontBaseSize,
        line_height_base: LineHeightBase,
    ) -> CSSPixelLength {
        let result = self.to_computed_value_for_math(context, base_size, line_height_base);
        if self.length_unit().is_viewport_percentage() {
            result.normalized()
        } else {
            result.finite()
        }
    }

fn to_computed_value_for_math(
        &self,
        context: &Context,
        base_size: FontBaseSize,
        line_height_base: LineHeightBase,
    ) -> CSSPixelLength {
        if let Some(px) = self.to_px_if_absolute() {
            if context.in_registered_value() {
                return CSSPixelLength::new(px);
            }
            return CSSPixelLength::new(px).zoom(context.builder.effective_zoom);
        }
        let unit = self.length_unit();
        if unit.is_font_relative() {
            let value = self.font_relative_to_computed_value(context, base_size, line_height_base);
            return if context.in_registered_value() {
                CSSPixelLength::new(context.builder.effective_zoom.unzoom(value.px()))
            } else {
                value
            };
        }
        if unit.is_viewport_percentage() {
            return self.viewport_percentage_to_computed_value(context);
        }
        if unit.is_container_relative() {
            return self.container_relative_to_computed_value(context);
        }
        debug_assert_eq!(unit, LengthUnit::ServoCharacterWidth);
        let value = self.servo_character_width_to_computed_value(
            context
                .style()
                .get_font()
                .slow_clone_font_size()
                .computed_size(),
        );
        if context.in_registered_value() {
            CSSPixelLength::new(context.builder.effective_zoom.unzoom(value.px()))
        } else {
            value
        }
    }

fn maybe_zoom_text(&self, size: CSSPixelLength) -> CSSPixelLength {
        if self
            .style()
            .get_font()
            .get__x_text_scale()
            .text_zoom_enabled()
        {
            self.device().zoom_text(size)
        } else {
            size
        }
    }

fn calc_line_height(
        &self,
        device: &Device,
        line_height_base: LineHeightBase,
        writing_mode: WritingMode,
    ) -> computed::NonNegativeLength {
        use crate::computed_value_flags::ComputedValueFlags;
        let (font, flag) = match line_height_base {
            LineHeightBase::CurrentStyle => (
                self.get_font(),
                ComputedValueFlags::DEPENDS_ON_SELF_FONT_METRICS,
            ),
            LineHeightBase::InheritedStyle => (
                self.get_parent_font(),
                ComputedValueFlags::DEPENDS_ON_INHERITED_FONT_METRICS,
            ),
        };
        let line_height = font.get_line_height();
        if matches!(line_height, computed::LineHeight::Normal) {
            self.add_flags(flag);
        }
        let lh = device.calc_line_height(font, writing_mode, None);
        if line_height_base == LineHeightBase::InheritedStyle {
            // Apply our own zoom if our style source is the parent style.
            computed::NonNegativeLength::new(self.effective_zoom_for_inheritance.zoom(lh.px()))
        } else {
            lh
        }
    }

fn calc_line_height(
        &self,
        font: &crate::properties::style_structs::Font,
        writing_mode: WritingMode,
        element: Option<GeckoElement>,
    ) -> NonNegativeLength {
        let pres_context = self.pres_context();
        let line_height = font.get_line_height();
        let au = Au(unsafe {
            bindings::Gecko_CalcLineHeight(
                line_height,
                pres_context.map_or(std::ptr::null(), |pc| pc),
                writing_mode.is_text_vertical(),
                &**font,
                element.map_or(std::ptr::null(), |e| e.0),
            )
        });
        NonNegativeLength::new(au.to_f32_px())
    }

static inline nscoord ComputeLineHeight(const StyleLineHeight& aLh,
                                        const nsFont& aFont, nsAtom* aLanguage,
                                        bool aExplicitLanguage,
                                        nsPresContext* aPresContext,
                                        bool aIsVertical,
                                        float aFontSizeInflation) {
  if (aLh.IsLength()) {
    nscoord result = aLh.AsLength().ToAppUnits();
    if (aFontSizeInflation != 1.0f) {
      result = NSToCoordRound(static_cast<float>(result) * aFontSizeInflation);
    }
    return result;
  }

  if (aLh.IsNumber()) {
    // For factor units the computed value of the line-height property
    // is found by multiplying the factor by the font's computed size
    // (adjusted for min-size prefs and text zoom).
    return aFont.size.ScaledBy(aLh.AsNumber() * aFontSizeInflation)
        .ToAppUnits();
  }

  MOZ_ASSERT(aLh.IsNormal());

  auto size = aFont.size;
  size.ScaleBy(aFontSizeInflation);

  if (aPresContext) {
    nsFont font = aFont;
    font.size = size;
    nsFontMetrics::Params params;
    params.language = aLanguage;
    params.explicitLanguage = aExplicitLanguage;
    params.orientation =
        aIsVertical ? nsFontMetrics::eVertical : nsFontMetrics::eHorizontal;
    params.userFontSet = aPresContext->GetUserFontSet();
    params.textPerf = aPresContext->GetTextPerfMetrics();
    params.featureValueLookup = aPresContext->GetFontFeatureValuesLookup();
    RefPtr<nsFontMetrics> fm = aPresContext->GetMetricsFor(font, params);
    return GetNormalLineHeight(fm);
  }
  // If we don't have a pres context, use a 1.2em fallback.
  size.ScaleBy(ReflowInput::kNormalLineHeightFactor);
  return size.ToAppUnits();
}

nscoord ReflowInput::CalcLineHeight(const StyleLineHeight& aLh,
                                    const nsStyleFont& aRelativeToFont,
                                    nsPresContext* aPresContext,
                                    bool aIsVertical,
                                    const nsIContent* aContent,
                                    float aFontSizeInflation) {
  nscoord lineHeight = ComputeLineHeight(
      aLh, aRelativeToFont.mFont, aRelativeToFont.GetLangAtom(),
      aRelativeToFont.mExplicitLanguage, aPresContext, aIsVertical,
      aFontSizeInflation);

  NS_ASSERTION(lineHeight >= 0, "ComputeLineHeight screwed up");

  const auto* input = HTMLInputElement::FromNodeOrNull(aContent);
  if (input && input->IsSingleLineTextControl()) {
    // For Web-compatibility, single-line text input elements cannot
    // have a line-height smaller than 'normal'.
    if (!aLh.IsNormal()) {
      nscoord normal = ComputeLineHeight(
          StyleLineHeight::Normal(), aRelativeToFont.mFont,
          aRelativeToFont.GetLangAtom(), aRelativeToFont.mExplicitLanguage,
          aPresContext, aIsVertical, aFontSizeInflation);
      if (lineHeight < normal) {
        lineHeight = normal;
      }
    }
  }

  return lineHeight;
}

Gecko_CalcLineHeight(const StyleLineHeight* aLh,
                             const nsPresContext* aPc, bool aVertical,
                             const nsStyleFont* aAgainstFont,
                             const mozilla::dom::Element* aElement) {
  // Normal line-height depends on font metrics.
  MutexAutoLock guard(*sServoFFILock);
  return ReflowInput::CalcLineHeight(*aLh, *aAgainstFont,
                                     const_cast<nsPresContext*>(aPc), aVertical,
                                     aElement, 1.0f);
}

fn from_unit(value: &CowRcStr) -> Self {
        // For registered properties, any reference to font-relative dimensions
        // make it dependent on font-related properties.
        // TODO(dshin): When we unit algebra gets implemented and handled -
        // Is it valid to say that `calc(1em / 2em * 3px)` triggers this?
        if value.eq_ignore_ascii_case(NoCalcLength::LH) {
            return Self::FONT_UNITS | Self::LH_UNITS | Self::FONT_METRICS | Self::FONT_ORIENTATION;
        }
        if value.eq_ignore_ascii_case(NoCalcLength::EM) {
            return Self::FONT_UNITS;
        }
        if value.eq_ignore_ascii_case(NoCalcLength::EX)
            || value.eq_ignore_ascii_case(NoCalcLength::CAP)
        {
            return Self::FONT_UNITS | Self::FONT_METRICS;
        }
        if value.eq_ignore_ascii_case(NoCalcLength::CH)
            || value.eq_ignore_ascii_case(NoCalcLength::IC)
        {
            return Self::FONT_UNITS | Self::FONT_METRICS | Self::FONT_ORIENTATION;
        }
        if value.eq_ignore_ascii_case(NoCalcLength::RLH) {
            return Self::ROOT_FONT_UNITS
                | Self::ROOT_LH_UNITS
                | Self::ROOT_FONT_METRICS
                | Self::ROOT_FONT_ORIENTATION;
        }
        if value.eq_ignore_ascii_case(NoCalcLength::REM) {
            return Self::ROOT_FONT_UNITS;
        }
        if value.eq_ignore_ascii_case(NoCalcLength::REX)
            || value.eq_ignore_ascii_case(NoCalcLength::RCAP)
        {
            return Self::ROOT_FONT_UNITS | Self::ROOT_FONT_METRICS;
        }
        if value.eq_ignore_ascii_case(NoCalcLength::RCH)
            || value.eq_ignore_ascii_case(NoCalcLength::RIC)
        {
            return Self::ROOT_FONT_UNITS | Self::ROOT_FONT_METRICS | Self::ROOT_FONT_ORIENTATION;
        }
        Self::empty()
    }

fn resume_metric_preparation(
        &self,
        context: &mut computed::Context,
        cache: &mut ShorthandsWithPropertyReferencesCache,
        attribute_tracker: &mut AttributeTracker,
        state: &mut MetricPreparation,
        completed: &PrioritaryPropertyIdSet,
        mut resolved_reference: Option<Arc<UnparsedValue>>,
    ) -> MetricPreparationStep {
        let longhand = state.longhand;
        let priority = PrioritaryPropertyId::from_longhand(longhand);
        if priority.is_some_and(|id| self.ensured_prioritary.contains(id))
            || state.flags != context.included_cascade_flags
            || self.seen.longhands.contains(longhand)
            || self.reverted.longhands.get(&longhand).copied() != state.initial_revert
        {
            return MetricPreparationStep::Invalidated;
        }
        if let Some(id) = priority {
            let prerequisites = id.dependencies();
            if !completed.contains_all(prerequisites) {
                return MetricPreparationStep::Prerequisites(prerequisites);
            }
        }
        loop {
            if state.complete {
                return MetricPreparationStep::Complete;
            }
            let Some(index) = state.cursor else {
                state.complete = true;
                continue;
            };
            let entry = state.declarations.longhand_declarations[index];
            if let Some(value) = state.waiting.as_ref() {
                let Some(resolved) = resolved_reference.take() else {
                    return MetricPreparationStep::References(longhand, value.clone());
                };
                if !std::ptr::eq(value.as_ref(), resolved.as_ref()) {
                    return MetricPreparationStep::Invalidated;
                }
                let declaration = self
                    .substitute_variables_if_needed(context, cache, entry.decl, attribute_tracker)
                    .into_owned();
                state.waiting = None;
                resolved_reference = None;
                state.retain(declaration, entry.priority);
                continue;
            }
            if !(entry.priority.flags() - state.flags).is_empty()
                || state.revert.is_some_and(|(priority, kind)| {
                    !priority.allows_when_reverted(&entry.priority, kind)
                })
            {
                state.advance();
                continue;
            }
            if let PropertyDeclaration::WithVariables(value) = entry.decl {
                state.waiting = Some(value.value.clone());
                resolved_reference = None;
                continue;
            }
            state.retain(entry.decl.clone(), entry.priority);
        }
    }

fn publish_prepared_metric<'a, 'b>(
        &mut self,
        context: &mut computed::Context,
        cache: &mut ShorthandsWithPropertyReferencesCache,
        attribute_tracker: &mut AttributeTracker,
        state: MetricPreparation<'a, 'b>,
        completed: &PrioritaryPropertyIdSet,
    ) -> Result<(), MetricPreparation<'a, 'b>> {
        let longhand = state.longhand;
        let priority = PrioritaryPropertyId::from_longhand(longhand);
        if priority.is_some_and(|id| self.ensured_prioritary.contains(id))
            || !state.complete
            || state.waiting.is_some()
            || priority.is_some_and(|id| !completed.contains_all(id.dependencies()))
            || state.flags != context.included_cascade_flags
            || self.seen.longhands.contains(longhand)
            || self.reverted.longhands.get(&longhand).copied() != state.initial_revert
        {
            return Err(state);
        }
        for entry in state.prepared {
            self.apply_one_longhand(
                context,
                longhand,
                &entry.declaration,
                entry.priority,
                cache,
                attribute_tracker,
            );
        }
        if let Some(id) = priority {
            if self.seen.longhands.contains(longhand) {
                self.did_apply_prioritary_property(context, id);
            }
            self.ensured_prioritary.insert(id);
        }
        Ok(())
    }
